import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_cute_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int VecSize, int Threads>
__global__ void sigmoid_kernel(const T* __restrict__ X,
                                T* __restrict__ Y,
                                int64_t total_elems,
                                int64_t num_tiles)
{
  constexpr int TileElems = Threads * VecSize;
  // Full 1D tensors over global memory
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(total_elems), make_stride(Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(total_elems), make_stride(Int<1>{}));
  // Grid-stride loop over tiles: each block processes multiple tiles,
  // reducing kernel launch overhead / grid size while keeping full coverage.
  for (int64_t tile_idx = blockIdx.x; tile_idx < num_tiles; tile_idx += gridDim.x) {
    int64_t tile_base = tile_idx * (int64_t)TileElems;
    int64_t remaining = total_elems - tile_base;
    if (remaining <= 0) continue;
    int64_t this_tile = remaining < (int64_t)TileElems ? remaining : (int64_t)TileElems;
    if (this_tile == (int64_t)TileElems) {
      // Full tile: safe to use CuTe tiling + partition + vectorized copy
      Tensor gX = local_tile(mX, make_shape(Int<TileElems>{}), make_coord(tile_idx));
      Tensor gY = local_tile(mY, make_shape(Int<TileElems>{}), make_coord(tile_idx));
      Tensor gX_v = make_tensor(gX.data(), make_shape(Int<Threads>{}, Int<VecSize>{}),
                                 make_stride(Int<VecSize>{}, Int<1>{}));
      Tensor gY_v = make_tensor(gY.data(), make_shape(Int<Threads>{}, Int<VecSize>{}),
                                 make_stride(Int<VecSize>{}, Int<1>{}));
      Tensor tXg = gX_v(threadIdx.x, _);
      Tensor tYg = gY_v(threadIdx.x, _);
      Tensor rX = make_tensor_like(tXg);
      copy(tXg, rX);
      #pragma unroll
      for (int i = 0; i < VecSize; ++i) {
        float v = static_cast<float>(rX(i));
        float s = 1.0f / (1.0f + __expf(-v));
        rX(i) = static_cast<T>(s);
      }
      copy(rX, tYg);
    } else {
      // Tail tile: element-wise fallback, still using CuTe tensor indexing
      int tid = threadIdx.x;
      for (int64_t idx = tid; idx < this_tile; idx += Threads) {
        int64_t g = tile_base + idx;
        float v = static_cast<float>(mX(g));
        float s = 1.0f / (1.0f + __expf(-v));
        mY(g) = static_cast<T>(s);
      }
    }
  }
}
torch::Tensor sigmoid_cute_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);
  int64_t total_elems = x_c.numel();
  constexpr int Threads = 256;
  constexpr int VecSize = 4;
  constexpr int TileElems = Threads * VecSize;
  int64_t num_tiles = (total_elems + TileElems - 1) / TileElems;
  // Cap the grid size and let each block process multiple tiles via a
  // grid-stride loop. This reduces block-launch/scheduling overhead for
  // very large tensors while keeping full coverage and coalesced access.
  const int64_t max_blocks = (int64_t)65535;
  int64_t grid_size = num_tiles < max_blocks ? num_tiles : max_blocks;
  if (grid_size < 1) grid_size = 1;
  dim3 block(Threads);
  dim3 grid((unsigned int)grid_size);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  sigmoid_kernel<float, VecSize, Threads><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      total_elems,
      num_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sigmoid_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["sigmoid_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CuTe CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_cute_forward(x)

